#!/usr/bin/env python3
"""Self-contained Astra P3 hidden representation compiler and synthesis checks.

Run with Python 3 (standard library only). The default executes the raw-program
compiler and exact summary-classifier checks. --full-checks also executes the
uniform and heterogeneous raw-ANF suites. Results are written beside this file.

Public handles after import:
  acquire_raw(poly_masks, original_input_count, rank_budget)
  compile_program(original_input_count, xor_and_instructions)
  iter_fibers(acquired_record, cache_characters=False)
  exact_reconstruct(acquired_record)

The finite leaf counter is exhaustive. This is NOT an implementation of the
asymptotic replacement-form phase engine and makes no practical speed claim.
All seven original modules are embedded verbatim and remain inspectable.
"""
import json
import sys
import types
from pathlib import Path

